def cc(n):
    s = ''
    while n != 0:
        s = str(n % 4) +  s
        n //= 4
    return s

def f(n):
    s = cc(n)
    if s[0] == '3':
        s = s.replace('1','*').replace('3','1').replace('*','1')
        s = '21' + s
    else:
        s += '12'
        s = '1' + s[1:]
    return int(s,4)

